#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Rebuild standalone HTML without external packages; optional mistune for docs."""
from pathlib import Path
import json,html,re
ROOT=Path(__file__).resolve().parent
AUTHOR_NAV='<a href="https://metaver.vip/" target="_blank" rel="noopener noreferrer">Andy 官网 ↗</a>'
AUTHOR_CONTACT='求职、职业发展或 AI 应用遇到具体问题，可自愿咨询 Andy：微信 <strong>AIPMAndy</strong> · <a href="https://metaver.vip/" target="_blank" rel="noopener noreferrer">Andy 官网 ↗</a>。免费内容完整可用，咨询不承诺晋升或录用结果。'

def build():
    data=json.loads((ROOT/'data/guide.json').read_text(encoding='utf-8'))
    css=(ROOT/'assets/style.css').read_text(encoding='utf-8')
    math=(ROOT/'assets/math.js').read_text(encoding='utf-8')
    app=(ROOT/'assets/app.js').read_text(encoding='utf-8')
    raw=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    evidence_ids=['EV01','EV02','EV05','EV06','EV07','EV11']
    evidence_byid={e['id']:e for e in data['evidence']}
    source_byid={s['id']:s for s in data['sources']}
    cards=[]
    for eid in evidence_ids:
        e=evidence_byid[eid]
        source=source_byid[e['source_id']]
        cards.append('<article class="evidence-card"><div class="ev-meta">'+html.escape(e['id'])+' · '+html.escape(e['type'])+'</div><div class="ev-number">'+html.escape(e['number'])+'</div><h3>'+html.escape(e['headline'])+'</h3><p>'+html.escape(e['what'])+'</p><p class="ev-limits"><strong>不能这样推：</strong>'+html.escape(e['limits'])+'</p><a target="_blank" rel="noopener noreferrer" href="'+html.escape(source['url'],quote=True)+'">查原始研究 ↗</a> · <a href="evidence/RESEARCH_ATLAS.html#'+eid.lower()+'">看证据边界</a></article>')
    evidence_section='<section class="evidence-section" id="evidence"><div class="section-title"><h2>先看硬证据，再跟着做</h2></div><p class="sub">企业原始披露、研究数据、元分析。数字只支持对应的结论，不表示个人升职概率。</p><div class="evidence-cards">'+''.join(cards)+'</div><div class="evidence-images"><figure><img src="evidence/manager-engagement-2022-2025.svg" loading="lazy" alt="2022至2025全球经理与非经理敬业度对比，Gallup 2026数据二次绘图"><figcaption>根据Gallup2026公开数据重绘；敬业度不能代替管理能力或晋升概率。</figcaption></figure><figure><img src="evidence/internal-mobility-leadership.svg" loading="lazy" alt="内部流动率高的企业晋升次数相对对比，低组100、高组179"><figcaption>根据LinkedIn2024企业观察重绘；相关性不证明内部流动导致晋升。</figcaption></figure></div><p><a class="btn primary" href="evidence/RESEARCH_ATLAS.html">查看14张完整证据卡及原始链接 →</a> <a class="btn" href="evidence/CASE_STUDIES.html">3个真实企业案例</a> <a class="btn" href="audit/EVIDENCE_AUDIT.html">对抗审查报告</a></p></section>'
    resources=''.join(f'<div class="resource"><a href="{html.escape(s["url"],quote=True)}" target="_blank" rel="noopener noreferrer">{html.escape(s["title"])} ↗</a><small>{html.escape(s["org"])} · 核验 {s["checked"]}</small></div>' for s in data['sources'])
    index=f'''<!DOCTYPE html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="普通人成为高管保姆级指南：7个阶段84项行动，从骨干到项目Owner、团队经理、业务负责人及高管候选，内含自评、90天计划和免费模板。"><title>普通人成为高管保姆级指南 · AI酋长 Andy</title><style>{css}</style></head><body><a class="skip" href="#actions">跳过导航</a><header class="header"><div class="wrap header-inner"><a class="brand" href="#top">普通人成为高管 ↗</a><nav class="nav" aria-label="主要导航"><a href="#route">找到路径</a><a href="playbooks/01-first-week.html">实操SOP</a><a href="#actions">行动清单</a><a href="#tools">免费工具</a><a href="#evidence">原始证据</a><a href="#references">参考来源</a>{AUTHOR_NAV}</nav></div></header><main><div class="wrap"><section class="hero" id="top"><div><div class="eyebrow">OPEN SOURCE · REAL EVIDENCE · 2026</div><h1>普通人成为高管<br><span>保姆级指南。</span></h1><p class="lead">从一个人把任务做好，到负责项目、带团队、经营业务，再到争取更大职责。用可核实的结果逐级升级，不靠空话，也不承诺“90天必升职”。</p><div class="cta"><a class="btn primary" href="#route">从我的阶段开始 →</a><a class="btn" href="guides/00-start.html">先读3分钟指南</a><a class="btn" href="playbooks/06-promotion-sponsor.html">高管晋升实操</a></div></div><aside class="hero-note"><div><div class="small">THE MANAGEMENT PATH</div><div class="big">07</div><div class="tiny">阶段清晰，任务可执行<br>用证据争取更大责任范围</div></div><div class="mini-grid"><div><strong>{len(data["tasks"])}</strong><span class="tiny">行动任务</span></div><div><strong>{sum(1 for x in (ROOT/"templates").glob("*.md"))+sum(1 for x in (ROOT/"templates").glob("*.csv"))}</strong><span class="tiny">实用模板</span></div><div><strong>0</strong><span class="tiny">账号和后端</span></div></div></aside></section><aside class="notice"><strong>请先确认：</strong>公司给你的“总监、VP”等Title不自动等于《公司法》中的法定高级管理人员。是否晋升取决于真实能力、组织机会、任命和其他条件；本项目自评不会预测录用率或晋升概率。</aside><div class="metrics"><span><b>7</b> 成长阶段</span><span><b>{len(data['tasks'])}</b> 可勾选任务</span><span><b>8</b> 维能力自评</span><span><b>{sum(1 for x in (ROOT/"templates").glob("*.md"))+sum(1 for x in (ROOT/"templates").glob("*.csv"))}</b> 免费模板</span></div><section class="panel route" id="route"><span class="eyebrow">STEP 0 · 3 MINUTES</span><h2>你现在在哪一层？下一步应该争取什么？</h2><p class="sub">只用作路线导航，不自动判断你的真实资质、晋升条件或招聘结果。</p><div class="route-grid"><label>当前最接近的工作角色<select id="current"><option value="employee">普通员工/项目执行者</option><option value="expert">专业骨干/资深专家</option><option value="owner">项目Owner/跨团队负责人</option><option value="manager">一线团队经理</option><option value="business">业务/职能负责人</option><option value="promotion">高管候选/新任负责人</option></select></label><label>你希望发展的路径<select id="goal"><option value="manager">业务管理与高管路线</option><option value="expert">专业专家路线（不强求带人）</option></select></label></div><div id="route-result" class="route-result" aria-live="polite"></div></section>{evidence_section}<section class="layout" id="actions"><aside class="sidebar"><h2>七个阶段</h2><div id="stages" class="stages"></div><div class="note">进度仅保存在本设备的浏览器。请勿把客户、同事或公司机密填入公开网页与Issues。<p><button id="clear" class="smallbtn" type="button">清空本地进度</button></p></div></aside><div><div class="panel"><h2>今天做什么？</h2><p class="sub">每项任务都包含动作、完成证据和卡住后的替代路径。对没有权限的事情，不建议越权执行。</p><div class="toolbar"><input id="search" type="search" placeholder="搜索：晋升、预算、授权、管理、项目……" aria-label="搜索任务"><button id="jump" class="smallbtn" type="button">全部</button></div><div class="progressbar" id="bar" role="progressbar" aria-label="任务完成度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><div id="bar-fill"></div></div><div class="progress-text"><span>已完成 <b id="done">0</b> / <span id="all">{len(data['tasks'])}</span></span><span id="pct">0%</span></div></div><div class="section-title"><h2 id="list-title">全部行动任务</h2><p class="sub" id="task-count">{len(data['tasks'])} 项</p></div><div id="cards" class="cards"></div></div></section><section id="tools" class="tools"><div class="section-title"><h2>两个免费工具</h2><p class="sub">无账号 · 本地保存 · 随时导出</p></div><div class="tools-grid"><div class="panel tool"><h2>8维能力证据自评</h2><p class="sub">每维0—3分：0没有案例，1参与，2独立交付，3能复用或带人。分数只是自我复盘索引。</p><div id="score-rows" class="score-rows"></div><div id="score-result" class="result" aria-live="polite"></div><p class="hint">没有验证过的心理测量效度，不能用来断定你是否适合高管，也不能预测薪酬或晋升。</p></div><div class="panel tool"><h2>我的90天行动计划</h2><p class="sub">别一次同时攻克所有短板。填三个真实、可验收的重点，导出并每周复盘。</p><div class="field"><label>重点1：责任扩大与结果<input id="p1" placeholder="例：负责一个明确授权的跨部门试点"></label><label>重点2：管理/经营证据<input id="p2" placeholder="例：形成一份有指标基线的项目复盘"></label><label>重点3：完成标准与复盘<input id="p3" placeholder="例：第30天验收，90天形成总结"></label></div><div class="cta"><button class="btn primary" id="export" type="button">导出我的计划和进度 ↓</button></div><p class="hint">真实材料应保存在自己合法控制的私有目录；公开分享前做好脱敏。</p></div></div></section><div class="wrap"><div class="panel" style="margin:30px 0;padding:22px"><h2>可填写的高管成长工作簿</h2><p class="sub">7个工作表，覆盖岗位JD、成果归因、授权、经营试算、晋升与90天行动。纯本地文件，不上传个人内容。</p><p><a class="btn primary" href="templates/普通人成为高管_完整实操工作簿.xlsx" download>下载完整 Excel 工作簿 ↓</a> <a class="btn" href="playbooks/01-first-week.html">跟着第一周SOP填写</a></p></div></div><section class="links" id="references"><h2>有来源，也有边界</h2><p class="sub">相关理论参考公开研究与法条。作者设计的7阶段和自评表并非任何机构认证的职业晋升量表。</p><div class="source-grid">{resources}</div></section></div></main><footer class="footer"><div class="wrap"><span>AI酋长 Andy 发起 · 原创内容 CC BY 4.0 · 代码 MIT</span><span>核验于 {data['reviewed_at']} · <a href="audit/ADVERSARIAL_REVIEW.html">对抗式审核</a> · <a href="REFERENCES.html">资料来源</a></span><p>{AUTHOR_CONTACT}</p></div></footer><div id="toast" class="toast" role="status" hidden></div><script id="data" type="application/json">{raw}</script><script>{math}</script><script>{app}</script></body></html>'''
    (ROOT/'index.html').write_text(index,encoding='utf-8')
    try:
        import mistune
    except ImportError as exc:
        raise RuntimeError('Rebuilding documentation requires: python3 -m pip install -r requirements-dev.txt') from exc
    reader=mistune.create_markdown(escape=True,plugins=['table'])
    files=[*ROOT.glob('evidence/*.md'),*ROOT.glob('guides/*.md'),*ROOT.glob('templates/*.md'),*ROOT.glob('playbooks/*.md'),*ROOT.glob('tracks/*.md'),*ROOT.glob('audit/*.md'),ROOT/'REFERENCES.md',ROOT/'CONTENT_LICENSE.md',ROOT/'PUBLISH.md',ROOT/'CONTRIBUTING.md',ROOT/'README.md']
    num=0
    for p in files:
        if not p.exists():continue
        rawmd=p.read_text(encoding='utf-8')
        body=reader(rawmd)
        if p.parent.name=='evidence':
            for e in data['evidence']:
                body=body.replace('<h3>'+e['id']+'｜','<h3 id="'+e['id'].lower()+'">'+e['id']+'｜')
        body=re.sub(r'href="([^"]+)\.md(#[^"]*)?"',lambda m:'href="'+m.group(1)+'.html'+(m.group(2)or'')+'"',body)
        title=next((x.lstrip('# ').strip() for x in rawmd.splitlines() if x.startswith('# ')),p.stem)
        prefix='../' if p.parent!=ROOT else ''
        page=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} · 普通人成为高管指南</title><style>body{{background:#f7f9fc;color:#1e293b;font:16px/1.9 -apple-system,"Noto Sans CJK SC","PingFang SC",sans-serif;margin:0}}header{{padding:14px 20px;background:white;border-bottom:1px solid #e1e6ee;position:sticky;top:0;z-index:2}}header nav{{display:flex;flex-wrap:wrap;gap:10px 20px}}header a{{margin-right:0}}.author-contact{{max-width:820px;margin:25px auto 45px;padding:0 20px;font-size:14px;color:#64748b;overflow-wrap:anywhere}}main{{max-width:820px;margin:25px auto 70px;padding:26px 35px;background:#fff;border:1px solid #e0e6ef;border-radius:16px}}h1{{font-size:30px;line-height:1.4}}h2{{font-size:23px;margin-top:38px}}h3{{font-size:19px}}a{{color:#235ed9;text-decoration:none}}a:hover{{text-decoration:underline}}p,li{{line-height:1.9}}blockquote{{border-left:3px solid #aac3ef;padding:7px 18px;background:#f6f9ff;margin:20px 0}}table{{width:100%;border-collapse:collapse;min-width:530px}}td,th{{border:1px solid #dce4ef;padding:8px;vertical-align:top;font-size:14px}}th{{background:#f3f6fb}}main{{overflow-x:auto}}pre{{overflow:auto;background:#192c44;color:white;padding:15px;border-radius:8px}}code{{background:#f1f4f8;padding:2px 4px}}pre code{{background:transparent}}img{{max-width:100%}}@media(max-width:650px){{main{{margin:10px;padding:18px;border-radius:0}}h1{{font-size:25px}}h2{{font-size:21px}}}}</style></head><body><header><nav aria-label="主要导航"><a href="{prefix}index.html">← 返回互动指南</a><a href="{prefix}README.html">项目目录</a><a href="{prefix}guides/00-start.html">从这里开始</a>{AUTHOR_NAV}</nav></header><main>{body}</main><footer class="author-contact">{AUTHOR_CONTACT}</footer></body></html>'''
        p.with_suffix('.html').write_text(page,encoding='utf-8');num+=1
    import seo_meta
    seo_meta.apply(ROOT)
    print('Rendered',num,'HTML reading pages')
    print('Generated index:',len(data['tasks']),'tasks',len(data['sources']),'references')

if __name__=='__main__':build()
